import { Button, Space } from 'antd';
import { PhoneOutlined } from '@ant-design/icons';
import { NavLink } from 'react-router-dom';
import { Header } from 'antd/es/layout/layout';
import logoWebsite from "../../assets/Imager/logogu.png";
import { Outlet } from "react-router-dom";
const HeaderDefault = () => {
    return (
        <>
            <Header className=" userlayout__header userlayout__header--top" style={{
                headerPadding: 0,
                display: 'flex',
                alignItems: 'center',
            }}
            >
                <Space className='header' size={0}>
                    {/* Trang chủ */}
                    <NavLink key={1} to="/">
                        <div className='header__logo'>
                            <img alt="logo" src={logoWebsite}></img>
                            <h2 className='header__setHide'>HT Haven</h2>
                        </div>
                    </NavLink>
                    {/* END trang chủ */}

                    {/* Ô tìm kiếm */}
                    <div className="header__searchBar">
                        {/* <SearchForm></SearchForm> */}
                    </div>
                    {/* END ô tìm kiếm */}

                    {/* Số điện thoại */}
                    <div className='header__phone'>
                        <a href='tel:039903378'>
                            <Button >
                                <div>
                                    <PhoneOutlined />
                                </div>
                                <div>
                                    <p>whatsapp:</p>
                                    <strong>039903378</strong>
                                </div>
                            </Button>
                        </a>
                    </div>
                    {/* END Số điện thoại */}
                    {/* <li>
                <NavLink key={2} to="/login">Login</NavLink>
              </li> */}
                </Space>
            </Header>

            <HeaderDefault className=" userlayout__header userlayout__header--bottom" style={{
                headerPadding: 0,
                display: 'flex',
                alignItems: 'center',
            }}
            >

            </HeaderDefault>
        </>
    )
};

export default HeaderDefault;
